-- NORMATIVE: one replacement kernel schema; factual revision history remains.
-- Durable kernel. Each database contains exactly one universe.
CREATE TABLE universes(id TEXT PRIMARY KEY, singleton INTEGER NOT NULL DEFAULT 1 UNIQUE CHECK(singleton=1), name TEXT NOT NULL);
CREATE TABLE record_identities(universe_id TEXT NOT NULL REFERENCES universes(id), id TEXT NOT NULL, kind TEXT NOT NULL, PRIMARY KEY(universe_id,id), UNIQUE(universe_id,id,kind));
CREATE TABLE record_versions(universe_id TEXT NOT NULL, id TEXT NOT NULL, record_id TEXT NOT NULL, kind TEXT NOT NULL,
 payload_row INTEGER NOT NULL REFERENCES r_payload(__row_id), digest TEXT NOT NULL,
 PRIMARY KEY(universe_id,id), UNIQUE(universe_id,id,record_id), FOREIGN KEY(universe_id,record_id,kind) REFERENCES record_identities(universe_id,id,kind));
-- Original hashes are import provenance, never a second active body or serializer.
CREATE TABLE import_record_digest(universe_id TEXT NOT NULL, version_id TEXT NOT NULL, source_digest TEXT NOT NULL, normalized_digest TEXT NOT NULL,
 PRIMARY KEY(universe_id,version_id), FOREIGN KEY(universe_id,version_id) REFERENCES record_versions(universe_id,id));
CREATE TABLE continuities(universe_id TEXT NOT NULL REFERENCES universes(id), id TEXT NOT NULL, head_commit TEXT NOT NULL, baseline_commit TEXT, PRIMARY KEY(universe_id,id), FOREIGN KEY(universe_id,head_commit,id) REFERENCES commits(universe_id,id,continuity_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(universe_id,baseline_commit) REFERENCES commits(universe_id,id));
CREATE TABLE commits(universe_id TEXT NOT NULL, id TEXT NOT NULL, continuity_id TEXT NOT NULL, parent_id TEXT, sequence INTEGER NOT NULL CHECK(sequence>=0), principal TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, digest TEXT NOT NULL, PRIMARY KEY(universe_id,id), UNIQUE(universe_id,continuity_id,sequence), UNIQUE(universe_id,id,continuity_id), FOREIGN KEY(universe_id,continuity_id) REFERENCES continuities(universe_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(universe_id,parent_id,continuity_id) REFERENCES commits(universe_id,id,continuity_id));
CREATE TABLE commit_changes(universe_id TEXT NOT NULL, revision_id TEXT NOT NULL, record_id TEXT NOT NULL, prior_version TEXT, version_id TEXT, PRIMARY KEY(universe_id,revision_id,record_id), FOREIGN KEY(universe_id,revision_id) REFERENCES commits(universe_id,id), FOREIGN KEY(universe_id,record_id) REFERENCES record_identities(universe_id,id), FOREIGN KEY(universe_id,prior_version,record_id) REFERENCES record_versions(universe_id,id,record_id), FOREIGN KEY(universe_id,version_id,record_id) REFERENCES record_versions(universe_id,id,record_id));
CREATE TABLE world_name_reservations(universe_id TEXT NOT NULL, name TEXT NOT NULL, record_id TEXT NOT NULL, first_revision TEXT NOT NULL, PRIMARY KEY(universe_id,name), FOREIGN KEY(universe_id,record_id) REFERENCES record_identities(universe_id,id), FOREIGN KEY(universe_id,first_revision) REFERENCES commits(universe_id,id));
CREATE TABLE head_membership(universe_id TEXT NOT NULL, continuity_id TEXT NOT NULL, record_id TEXT NOT NULL, version_id TEXT NOT NULL, PRIMARY KEY(universe_id,continuity_id,record_id), FOREIGN KEY(universe_id,continuity_id) REFERENCES continuities(universe_id,id), FOREIGN KEY(universe_id,version_id,record_id) REFERENCES record_versions(universe_id,id,record_id));
CREATE TABLE projection_heads(universe_id TEXT NOT NULL, continuity_id TEXT NOT NULL, revision_id TEXT NOT NULL, checksum TEXT NOT NULL, PRIMARY KEY(universe_id,continuity_id));
CREATE TABLE snapshot_membership(universe_id TEXT NOT NULL, revision_id TEXT NOT NULL,  checksum TEXT NOT NULL, PRIMARY KEY(universe_id,revision_id), FOREIGN KEY(universe_id,revision_id) REFERENCES commits(universe_id,id));
CREATE TABLE projection_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1), generation INTEGER NOT NULL);
INSERT INTO projection_state VALUES(1,0);
CREATE TABLE reference_index(generation INTEGER NOT NULL, version_id TEXT NOT NULL, target_record TEXT NOT NULL, target_version TEXT, path TEXT NOT NULL);
CREATE TABLE typed_projection(generation INTEGER NOT NULL, version_id TEXT NOT NULL, path TEXT NOT NULL, value TEXT NOT NULL);
CREATE TABLE world_projection(generation INTEGER NOT NULL, version_id TEXT NOT NULL, world_id TEXT NOT NULL);
CREATE TABLE narrative_projection(generation INTEGER NOT NULL, version_id TEXT NOT NULL, target_record TEXT NOT NULL, path TEXT NOT NULL);
CREATE VIRTUAL TABLE search_index USING fts5(generation UNINDEXED, version_id UNINDEXED, text);
CREATE INDEX reference_target ON reference_index(generation,target_record);
CREATE INDEX typed_lookup ON typed_projection(generation,path,value);
CREATE INDEX world_lookup ON world_projection(generation,world_id);
CREATE TABLE operation_receipts(universe_id TEXT NOT NULL REFERENCES universes(id), principal TEXT NOT NULL, operation_kind TEXT NOT NULL, idempotency_key TEXT NOT NULL, payload_digest TEXT NOT NULL, revision_id TEXT NOT NULL, PRIMARY KEY(universe_id,principal,operation_kind,idempotency_key), FOREIGN KEY(universe_id,revision_id) REFERENCES commits(universe_id,id));
CREATE TRIGGER immutable_record_identities_update BEFORE UPDATE ON record_identities BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_record_identities_delete BEFORE DELETE ON record_identities BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_record_versions_update BEFORE UPDATE ON record_versions BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_record_versions_delete BEFORE DELETE ON record_versions BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_commits_update BEFORE UPDATE ON commits BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_commits_delete BEFORE DELETE ON commits BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_commit_changes_update BEFORE UPDATE ON commit_changes BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_commit_changes_delete BEFORE DELETE ON commit_changes BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_world_name_reservations_update BEFORE UPDATE ON world_name_reservations BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_world_name_reservations_delete BEFORE DELETE ON world_name_reservations BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_operation_receipts_update BEFORE UPDATE ON operation_receipts BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_operation_receipts_delete BEFORE DELETE ON operation_receipts BEGIN SELECT RAISE(ABORT,'immutable canon history'); END;
CREATE TRIGGER immutable_branch BEFORE UPDATE OF universe_id,id,baseline_commit ON continuities BEGIN SELECT RAISE(ABORT,'immutable branch descriptor'); END;

CREATE TRIGGER immutable_universe_id BEFORE UPDATE OF id ON universes BEGIN SELECT RAISE(ABORT,'immutable universe identity'); END;
CREATE TRIGGER immutable_universe_delete BEFORE DELETE ON universes BEGIN SELECT RAISE(ABORT,'immutable universe identity'); END;

CREATE TABLE snapshot_member (universe_id TEXT NOT NULL, revision_id TEXT NOT NULL, record_id TEXT NOT NULL, version_id TEXT NOT NULL,
 PRIMARY KEY(universe_id,revision_id,record_id), FOREIGN KEY(universe_id,revision_id) REFERENCES snapshot_membership(universe_id,revision_id),
 FOREIGN KEY(universe_id,version_id,record_id) REFERENCES record_versions(universe_id,id,record_id)) STRICT;

CREATE TRIGGER immutable_import_digest_update BEFORE UPDATE ON import_record_digest BEGIN SELECT RAISE(ABORT,'immutable import provenance'); END;
CREATE TRIGGER immutable_import_digest_delete BEFORE DELETE ON import_record_digest BEGIN SELECT RAISE(ABORT,'immutable import provenance'); END;

-- Normative semantic projections over the single canonical model.
-- IDs below point to preserved universe/record identities, never labels.
CREATE TABLE type_definition (
 universe_id TEXT NOT NULL, version_id TEXT NOT NULL, record_id TEXT NOT NULL,
 name TEXT NOT NULL, parent_id TEXT, parent_resolution TEXT NOT NULL CHECK(parent_resolution IN ('root','resolved','ambiguous')), applicability TEXT NOT NULL CHECK(applicability IN ('universe','worlds','unspecified','conditional')),
 PRIMARY KEY(universe_id,version_id), UNIQUE(universe_id,version_id,record_id),
 FOREIGN KEY(universe_id,version_id,record_id) REFERENCES record_versions(universe_id,id,record_id),
 FOREIGN KEY(universe_id,parent_id) REFERENCES record_identities(universe_id,id),
 CHECK((parent_resolution='resolved' AND parent_id IS NOT NULL) OR (parent_resolution!='resolved' AND parent_id IS NULL))
) STRICT;
CREATE TABLE type_world (
 universe_id TEXT NOT NULL, version_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), world_id TEXT NOT NULL,
 PRIMARY KEY(universe_id,version_id,ordinal), UNIQUE(universe_id,version_id,world_id),
 FOREIGN KEY(universe_id,version_id) REFERENCES type_definition(universe_id,version_id),
 FOREIGN KEY(universe_id,world_id) REFERENCES record_identities(universe_id,id)
) STRICT;
CREATE TABLE instance_classification (
 universe_id TEXT NOT NULL, version_id TEXT NOT NULL, record_id TEXT NOT NULL, type_id TEXT,
 resolution TEXT NOT NULL CHECK(resolution IN ('resolved','unclassified','ambiguous')),
 PRIMARY KEY(universe_id,version_id),
 FOREIGN KEY(universe_id,version_id,record_id) REFERENCES record_versions(universe_id,id,record_id),
 FOREIGN KEY(universe_id,type_id) REFERENCES record_identities(universe_id,id),
 CHECK((resolution='resolved' AND type_id IS NOT NULL) OR (resolution!='resolved' AND type_id IS NULL))
) STRICT;
CREATE TABLE classification_evidence (
 universe_id TEXT NOT NULL, version_id TEXT NOT NULL, relationship TEXT NOT NULL CHECK(relationship IN ('parent','membership')),
 ordinal INTEGER NOT NULL CHECK(ordinal>=0), type_id TEXT NOT NULL,
 PRIMARY KEY(universe_id,version_id,relationship,ordinal),
 FOREIGN KEY(universe_id,version_id) REFERENCES record_versions(universe_id,id),
 FOREIGN KEY(universe_id,type_id) REFERENCES record_identities(universe_id,id)
) STRICT;
CREATE TABLE definition_attribute (
 universe_id TEXT NOT NULL, assertion_version TEXT NOT NULL, subject_id TEXT NOT NULL, predicate_id TEXT NOT NULL,
 mode TEXT NOT NULL CHECK(mode IN ('shared','initial_value')),
 PRIMARY KEY(universe_id,assertion_version),
 FOREIGN KEY(universe_id,assertion_version) REFERENCES record_versions(universe_id,id),
 FOREIGN KEY(universe_id,subject_id) REFERENCES record_identities(universe_id,id),
 FOREIGN KEY(universe_id,predicate_id) REFERENCES record_identities(universe_id,id)
) STRICT;
-- Values, scope, time, context, basis and polarity live in the typed assertion/proposition rows.
-- Separate initialization evidence prevents start/refinement/rename from becoming a refill.
CREATE TABLE initialization_receipt (
 universe_id TEXT NOT NULL, instance_id TEXT NOT NULL, start_event_id TEXT NOT NULL, predicate_id TEXT NOT NULL,
 initial_definition_version TEXT NOT NULL, assertion_version TEXT NOT NULL, revision_id TEXT NOT NULL, source_revision TEXT NOT NULL,
 PRIMARY KEY(universe_id,instance_id,start_event_id,predicate_id),
 FOREIGN KEY(universe_id,instance_id) REFERENCES record_identities(universe_id,id),
 FOREIGN KEY(universe_id,start_event_id) REFERENCES record_identities(universe_id,id),
 FOREIGN KEY(universe_id,predicate_id) REFERENCES record_identities(universe_id,id),
 FOREIGN KEY(universe_id,initial_definition_version) REFERENCES record_versions(universe_id,id),
 FOREIGN KEY(universe_id,assertion_version) REFERENCES record_versions(universe_id,id),
 FOREIGN KEY(universe_id,revision_id) REFERENCES commits(universe_id,id),
 FOREIGN KEY(universe_id,source_revision) REFERENCES commits(universe_id,id)
) STRICT;

-- Closed workflow families: typed pointers preserve exact historical key and digest.
CREATE TABLE workflow_entries (
 key TEXT PRIMARY KEY,
 family TEXT NOT NULL CHECK(family IN ('StoredContext','StoredProposal','Checked','StoredOperation','ApprovalEvidence','AssessmentEnvelope','AssessmentSelection','AssessmentReceipt','Cursor','Cancellation','ReservedRecord','SavedDraft','ImportOrigin','ImportAdmission')),
 digest TEXT NOT NULL,
 digest_recipe TEXT NOT NULL CHECK(digest_recipe IN ('workflow-canonical')),
 "StoredContext" INTEGER REFERENCES "r_stored_context"(__row_id),
 "StoredProposal" INTEGER REFERENCES "r_stored_proposal"(__row_id),
 "Checked" INTEGER REFERENCES "r_checked"(__row_id),
 "StoredOperation" INTEGER REFERENCES "r_stored_operation"(__row_id),
 "ApprovalEvidence" INTEGER REFERENCES "r_approval_evidence"(__row_id),
 "AssessmentEnvelope" INTEGER REFERENCES "r_assessment_envelope"(__row_id),
 "AssessmentSelection" INTEGER REFERENCES "r_assessment_selection"(__row_id),
 "AssessmentReceipt" INTEGER REFERENCES "r_assessment_receipt"(__row_id),
 "Cursor" INTEGER REFERENCES "r_cursor"(__row_id),
 "Cancellation" INTEGER REFERENCES "r_cancellation"(__row_id),
 "ReservedRecord" INTEGER REFERENCES "r_reserved_record"(__row_id),
 "SavedDraft" INTEGER REFERENCES "r_saved_draft"(__row_id),
 "ImportOrigin" INTEGER REFERENCES "r_import_origin"(__row_id),
 "ImportAdmission" INTEGER REFERENCES "r_import_admission"(__row_id),
 CHECK(family!='StoredContext' OR ("StoredContext" IS NOT NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='StoredProposal' OR ("StoredContext" IS NULL AND "StoredProposal" IS NOT NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='Checked' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NOT NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='StoredOperation' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NOT NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='ApprovalEvidence' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NOT NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='AssessmentEnvelope' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NOT NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='AssessmentSelection' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NOT NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='AssessmentReceipt' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NOT NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='Cursor' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NOT NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='Cancellation' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NOT NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='ReservedRecord' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NOT NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='SavedDraft' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NOT NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='ImportOrigin' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NOT NULL AND "ImportAdmission" IS NULL)),
 CHECK(family!='ImportAdmission' OR ("StoredContext" IS NULL AND "StoredProposal" IS NULL AND "Checked" IS NULL AND "StoredOperation" IS NULL AND "ApprovalEvidence" IS NULL AND "AssessmentEnvelope" IS NULL AND "AssessmentSelection" IS NULL AND "AssessmentReceipt" IS NULL AND "Cursor" IS NULL AND "Cancellation" IS NULL AND "ReservedRecord" IS NULL AND "SavedDraft" IS NULL AND "ImportOrigin" IS NULL AND "ImportAdmission" IS NOT NULL))
) STRICT;
CREATE TABLE source_content(digest TEXT PRIMARY KEY, byte_size INTEGER NOT NULL CHECK(byte_size>=0), utf8_content BLOB NOT NULL, workflow_digest TEXT NOT NULL) STRICT;
CREATE TABLE source_staging(key TEXT PRIMARY KEY, workflow_digest TEXT NOT NULL, source_version_row INTEGER NOT NULL REFERENCES r_payload(__row_id)) STRICT;
CREATE TABLE media_chunk(digest TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), byte_size INTEGER NOT NULL, content BLOB NOT NULL, historical_workflow_digest TEXT NOT NULL, PRIMARY KEY(digest,ordinal)) STRICT;
CREATE TABLE image_staging(key TEXT PRIMARY KEY, workflow_digest TEXT NOT NULL, image_asset_row INTEGER NOT NULL REFERENCES r_payload(__row_id)) STRICT;
CREATE TABLE continuity_name(continuity_id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, workflow_digest TEXT NOT NULL) STRICT;
-- BLOBs above are actual source/media content only, never application metadata.
CREATE TRIGGER workflow_entries_no_update BEFORE UPDATE ON workflow_entries BEGIN SELECT RAISE(ABORT,'immutable workflow entry'); END;
CREATE TRIGGER workflow_entries_no_delete BEFORE DELETE ON workflow_entries BEGIN SELECT RAISE(ABORT,'immutable workflow entry'); END;

-- One lookup index spans typed evidence and actual content; no serialized fallback.
CREATE VIEW workflow_index AS
 SELECT key,digest FROM workflow_entries
 UNION ALL SELECT 'source:'||digest,workflow_digest FROM source_content
 UNION ALL SELECT key,workflow_digest FROM source_staging
 UNION ALL SELECT 'image-bytes:'||digest||':'||ordinal,historical_workflow_digest FROM media_chunk
 UNION ALL SELECT key,workflow_digest FROM image_staging
 UNION ALL SELECT key,workflow_digest FROM continuity_name;
CREATE TRIGGER source_content_no_update BEFORE UPDATE ON source_content BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER source_content_no_delete BEFORE DELETE ON source_content BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER source_staging_no_update BEFORE UPDATE ON source_staging BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER source_staging_no_delete BEFORE DELETE ON source_staging BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER media_chunk_no_update BEFORE UPDATE ON media_chunk BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER media_chunk_no_delete BEFORE DELETE ON media_chunk BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER image_staging_no_update BEFORE UPDATE ON image_staging BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER image_staging_no_delete BEFORE DELETE ON image_staging BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER continuity_name_no_update BEFORE UPDATE ON continuity_name BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;
CREATE TRIGGER continuity_name_no_delete BEFORE DELETE ON continuity_name BEGIN SELECT RAISE(ABORT,'immutable workflow content'); END;

-- Imported workflows retain their original evidence and digest bindings.
-- Approvals, operations, contexts and cursors are excluded from active lookups;
-- proposals remain reviewable under the owning installation's current authority.
CREATE TABLE historical_workflow(key TEXT PRIMARY KEY REFERENCES workflow_entries(key)) STRICT;
CREATE TRIGGER historical_workflow_no_update BEFORE UPDATE ON historical_workflow BEGIN SELECT RAISE(ABORT,'immutable historical boundary'); END;
CREATE TRIGGER historical_workflow_no_delete BEFORE DELETE ON historical_workflow BEGIN SELECT RAISE(ABORT,'immutable historical boundary'); END;
CREATE TABLE historical_receipt(universe_id TEXT NOT NULL, principal TEXT NOT NULL, operation_kind TEXT NOT NULL, idempotency_key TEXT NOT NULL,
 PRIMARY KEY(universe_id,principal,operation_kind,idempotency_key), FOREIGN KEY(universe_id,principal,operation_kind,idempotency_key) REFERENCES operation_receipts(universe_id,principal,operation_kind,idempotency_key)) STRICT;
CREATE TRIGGER historical_receipt_no_update BEFORE UPDATE ON historical_receipt BEGIN SELECT RAISE(ABORT,'immutable historical boundary'); END;
CREATE TRIGGER historical_receipt_no_delete BEFORE DELETE ON historical_receipt BEGIN SELECT RAISE(ABORT,'immutable historical boundary'); END;
CREATE VIEW active_workflow_index AS SELECT key,digest FROM workflow_index WHERE key NOT IN (SELECT h.key FROM historical_workflow h JOIN workflow_entries e ON e.key=h.key WHERE e.family IN ('ApprovalEvidence','StoredOperation','StoredContext','Cursor'));

-- Conversion provenance binds original workflow evidence to normalized typed rows.
CREATE TABLE import_workflow_digest(key TEXT PRIMARY KEY, source_digest TEXT NOT NULL, normalized_digest TEXT NOT NULL) STRICT;
CREATE TRIGGER import_workflow_digest_no_update BEFORE UPDATE ON import_workflow_digest BEGIN SELECT RAISE(ABORT,'immutable import provenance'); END;
CREATE TRIGGER import_workflow_digest_no_delete BEFORE DELETE ON import_workflow_digest BEGIN SELECT RAISE(ABORT,'immutable import provenance'); END;
''';
